# region: render
def render(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
    return out

# region: fold
def fold(xs, offset=-1):
    return [v + offset for v in xs]

# region: gather
def gather(xs):
    acc = 0
    out = []
    for v in xs:
        acc = acc + v
        out.append(acc)
        return out
    return out

# region: shape
def shape(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: digest
def digest(summary, bar=3):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return digest(shape(gather(fold(render(raw)))))

